[1135] = { en = "Highperch Venom", tier = 2,
  t = "Gif uit Highperch",
  d = "Je weet misschien dat orks wyverns vaak temmen om op te rijden. Maar minder bekend is dat het gif van een wyvern in sommige kringen meer waard is dan het beest zelf. Dus als je niet bang bent om een beetje op wyverns te jagen... dan heb ik werk voor je.$B$BTen westen van hier, in het land van Thousand Needles, ligt een plek die Highperch heet. De wyverns van Highperch hebben een sterk gif. Sterk, en veel waard.",
