[1203] = { en = "Jarl Needs a Blade", tier = 2,
  t = "Jarl heeft een zwaard nodig",
  d = "Ik heb wat te snijden. Ik kan je niet zeggen wat ik ga snijden, maar... ik heb een zwaard nodig. Een bepaald zwaard...$B$BSommige mensen noemen het een moonsteel broadsword. Ik noem het een zwaaizwaard.$B$BHelp jij mij? Misschien vind je het in de stad. Misschien praat je met een smid, en maakt hij het speciaal voor jou.$B$BMaar wacht er niet te lang mee. Wat ik ga snijden, blijft niet eeuwig goed...",
