[1206] = { en = "Jarl Needs Eyes", tier = 2,
  t = "Jarl heeft ogen nodig",
  d = "Oogsap is goed sap om te drinken. Jammer dat de meeste beestjes maar twee ogen hebben.$B$BMaar spinnen hebben veel ogen. Heel veel. En oogsap van Darkmist is lekker. Zacht en zout! Ongeknapte spinnenogen... ik proef ze al.$B$BDarkmist-spinnen zitten ten westen van hier, in de Darkmist Cavern. Denk jij dat de spinnen naar de grot genoemd zijn... of is het andersom?",
  o = "Breng 40 Unpopped Darkmist Eyes naar \"Swamp Eye\" Jarl bij de Swamplight Manor.",
  p = "Waar zijn die ogen?",
  c = "Je hebt de ogen! Je hebt de ogen! Lekkere, lekkere spinnenogen!$B$BSommige ogen... als je ernaar staart, staren ze terug. Die eet je als laatste. Ze houden je gezelschap... buiten in het moeras.$B$BHallo, kleine spinnenogen. Hallo! Jullie smaken naar kip. Kleverige, zoute kip!$B$BMmmh.",
