[1253] = { en = "The Black Shield", tier = 2,
  t = "Het zwarte schild",
  d = "Een ijzeren schild hangt vast aan de afbrokkelende schoorsteen. Het is zwart geworden door het vuur dat door de herberg raasde. De schoorsteen is een van de weinige delen die nog over zijn van het gebouw dat ooit de Shady Rest Inn was.$b$bJe kunt het schild uit de bakstenen van de schoorsteen halen.",
