[1282] = { en = "They Call Him Smiling Jim", tier = 2,
  t = "Ze noemen hem Smiling Jim",
  d = "Ik heb gewoon medelijden met de oude Jim daar. Hij was niet altijd zo. Hij had een tijdje een herberg in het moeras, een prachtige plek.$b$bLuister, ik wil er niet echt over praten. Vraag het maar aan Captain Vimes als het echt moet.",
  o = "Praat met Captain Garran Vimes in Theramore.",
  c = "Zijn echte naam is James Hyal. Hij opende een herberg aan de rand van The Barrens. Hij wilde een fijne plek maken waar reizigers konden stoppen...$B$BMisschien dacht hij te groot, maar de herberg deed het een tijdje goed. Toen verloren we de controle over de wegen in het moeras, en namen de ogers het over.$B$BJames was te koppig om zijn droom op te geven voor de veiligheid binnen onze muren. De Shady Rest Inn is tot de grond toe afgebrand. We doen onderzoek, maar we hebben nog niet veel geluk gehad. Als je wilt helpen, kijk dan wat je in het puin kunt vinden.",
  g = { {"medelijden", "pity, sympathy"}, {"een tijdje", "for a while"}, {"prachtige", "wonderful (prachtig)"}, {"als het echt moet", "if you really have to"}, {"rand", "edge"}, {"reizigers", "travelers (reiziger)"}, {"verloren", "lost (verliezen)"}, {"ogers", "ogres (oger)"}, {"koppig", "stubborn"}, {"op te geven", "to give up (opgeven)"}, {"veiligheid", "safety"}, {"tot de grond toe afgebrand", "burnt to the ground"}, {"onderzoek", "investigation, research"}, {"puin", "rubble"} },
},

[1284] = { en = "Suspicious Hoofprints", tier = 2,
  t = "Verdachte hoefafdrukken",
  d = "Rijen hoefafdrukken lopen weg van het geraamte van de Shady Rest Inn, dat nog steeds rookt. Een paar afdrukken zijn goed te zien. Er zijn nog meer rijen, maar die zijn bijna niet te zien in de zachte modder van het moeras.",
  o = "Vertel Captain Garran Vimes in Theramore over de verdachte afdrukken bij de Shady Rest Inn.",
  c = "Hoefafdrukken, hè? Het is waar dat er buitengewoon veel centauren actief zijn in de gebieden bij de Dustwallow Marsh. Tijdens korte tochten in The Barrens hebben we hun kampen en bezittingen overal in de omgeving gevonden.$B$BIk stuur Falgran Hastil erop uit, een van onze spoorzoekers, om te kijken of hij kan vinden waar de sporen heen leiden.",
  g = { {"verdachte", "suspicious (verdacht)"}, {"hoefafdrukken", "hoofprints (hoefafdruk)"}, {"rijen", "rows (rij)"}, {"geraamte", "skeleton"}, {"rookt", "smokes (roken)"}, {"modder", "mud"}, {"buitengewoon", "extraordinarily"}, {"centauren", "centaurs (centaur)"}, {"tochten", "trips, excursions (tocht)"}, {"bezittingen", "holdings, possessions"}, {"omgeving", "area, surroundings"}, {"erop uit", "out (on a mission)"}, {"spoorzoekers", "trackers (spoorzoeker)"}, {"sporen", "tracks (spoor)"}, {"leiden", "lead"} },
},

[1319] = { en = "The Black Shield", tier = 2,
  t = "Het zwarte schild",
  d = "Het spijt me dat ik je niet veel kan helpen, $n. Maar ik kan je naar iemand sturen die dat wel kan. Caz Twosprocket, een van onze beste smeden, werkt bij het smidsvuur in de smederij.$b$bBreng het schild naar hem en kijk wat hij je kan vertellen.",
  o = "Laat het Blackened Iron Shield zien aan Caz Twosprocket in Theramore.",
  p = "Iets voor mij om naar te kijken?",
