  g = { {"het spijt me", "I'm sorry"}, {"smeden", "blacksmiths (smid)"}, {"smidsvuur", "forge (fire)"}, {"smederij", "smithy"}, {"schild", "shield"}, {"ijzer", "iron"}, {"zeker", "certainly, definitely"}, {"kant", "side"} },
