[1320] = { en = "The Black Shield", tier = 2,
  t = "Het zwarte schild",
  d = "Ah, dit had ik bijna gemist... Het leren riempje aan de achterkant is vast verbrand. Maar het lijkt gemaakt voor een groot persoon. Ik zou eigenlijk zeggen: een tauren.$b$bMeer kan ik je niet vertellen. Zeg tegen Captain Vimes dat het me spijt dat ik niet meer kon helpen.",
  o = "Praat met Captain Garran Vimes in Theramore.",
  c = "Dat is niet veel informatie om mee te werken, maar we moeten het onthouden. Hopelijk vallen de andere stukjes van dit mysterie ook op hun plek. Dan krijgen we een beter beeld van wat er gebeurd is.",
