[1222] = { en = "Stinky's Escape", tier = 3,
  t = "Stinky's ontsnapping",
  d = "Mooi, eindelijk iets dat me niet wil opeten!$B$BIk heb hulp nodig met de beesten hier, en jij lijkt me geschikt, $gmaat:dame;.$B$BDe kok Morgan Stern doet onderzoek naar een nieuw recept. Hij heeft me hierheen gestuurd om bladeren van het waterdrieblad te verzamelen. Ik denk dat hij ze lekker vindt.$B$BIn elk geval: terwijl ik een waterdrieblad zocht... werd ik omsingeld! Kun je me hier weg helpen, en op me letten terwijl ik naar het waterdrieblad zoek?",
  o = "Begeleid \"Stinky\" Ignatz en praat daarna met Morgan Stern in Theramore.",
  p = "Heb je meneer Ignatz gezien? Ik heb hem een tijd geleden het moeras in gestuurd en hij is niet teruggekomen!",
  c = "Meneer Ignatz was hier net met de bladeren van het waterdrieblad. Hij vertelde me dat je hem uit flinke problemen hebt geholpen.$B$BDank je, $N. Ik zal mijn oom vragen om je op een feestmaal te trakteren als je de volgende keer de Blue Recluse in Stormwind bezoekt.",
  e = "Help Stinky om Bogbean Leaves te vinden",
  g = { {"ontsnapping", "escape"}, {"geschikt", "suitable, fit"}, {"maat", "buddy, mate"}, {"dame", "lady"}, {"recept", "recipe"}, {"waterdrieblad", "bogbean (a marsh plant)"}, {"verzamelen", "to gather"}, {"in elk geval", "anyway"}, {"omsingeld", "surrounded (omsingelen)"}, {"op me letten", "watch my back (letten op)"}, {"begeleid", "escort (begeleiden)"}, {"flinke", "real, considerable (flink)"}, {"feestmaal", "feast"}, {"trakteren", "to treat"} },
},

[1271] = { en = "Feast at the Blue Recluse", tier = 3,
  t = "Feestmaal in de Blue Recluse",
  c = "Mijn neef zei dat je hem geholpen hebt met zijn onderzoek in Dustwallow, en dat je zijn collega uit een lastige situatie hebt gehaald. Nou, wij Sterns blijven bij elkaar en we negeren onze vrienden niet!$B$BDus was je handen, $N, want we gaan een feest geven ter ere van jou!",
  g = { {"neef", "nephew, cousin"}, {"collega", "colleague, associate"}, {"lastige", "tricky, difficult (lastig)"}, {"situatie", "situation"}, {"blijven bij elkaar", "stick together"}, {"negeren", "to ignore"}, {"was", "wash (wassen)"}, {"ter ere van", "in honor of"} },
},

[1273] = { en = "Questioning Reethe", tier = 3,
  t = "Reethe ondervragen",
  d = "Het duurde lang, maar ik heb Reethe gevonden. Hij kan goed verstoppen voor een mens.$b$bOgron bang dat hij misschien gek is na zo veel tijd in moeras. Jij komt met mij, want wij gaan antwoorden van hem halen.",
  o = "Ga met Ogron mee om met Reethe te praten, en ga dan terug naar Krog in Brackenwall Village.",
  p = "Heb je Reethe gevonden?",
  c = "Hm. Het is goed dat Reethe niet meer door het moeras sluipt. Maar het is jammer dat mensen zo zwak gebouwd zijn dat hij niet kon herstellen van een kleine pijlwond.$b$bHet lijkt erop dat dit spoor van het mysterie nergens heen leidde. We moeten ergens anders zoeken.",
  e = "Ondervraag Reethe met Ogron",
  g = { {"ondervragen", "to question, interrogate"}, {"verstoppen", "to hide"}, {"gek", "crazy"}, {"antwoorden", "answers (antwoord)"}, {"sluipt", "lurks, sneaks (sluipen)"}, {"zwak", "weak, frail"}, {"gebouwd", "built (bouwen)"}, {"herstellen", "to recover"}, {"pijlwond", "arrow wound"}, {"spoor", "trail, thread"}, {"leidde", "led (leiden)"}, {"ergens anders", "elsewhere"} },
