[1204] = { en = "Mudrock Soup and Bugs", tier = 3,
  t = "Mudrocksoep met beestjes",
  d = "Ik werk aan een gerecht dat ik \"Mudrocksoep met beestjes\" noem. Ik heb de belangrijkste ingrediënten nog nodig, en... nou, ik denk niet dat ik het lang zou volhouden als ik door Dustwallow Marsh moet ploeteren!$B$BDus, $N, wil je voor mij gaan jagen? Eerst heb ik de tongen van Mudrock-schildpadden nodig. Je vindt Mudrocks langs de kust, vooral rond de baai.$B$BMaar ik wil niet zomaar tongen! Ik heb gehoord dat sommige Mudrocks een gespleten tong hebben...$B$BMen zegt dat gespleten tongen een bijzondere smaak hebben, en die smaak wil ik in mijn gerecht...",
  o = "Breng 8 Forked Mudrock Tongues naar Morgan Stern in Theramore.",
  p = "Heb je de gespleten tongen?",
  c = "Deze zijn prima! Dank je, $N!$B$BNu ga ik verschillende kooktechnieken op deze tongen uitproberen, om de beste manier te vinden om hun smaak naar boven te halen.$B$BUiteindelijk heb ik een gerecht dat goed genoeg is om te serveren in de Blue Recluse in Stormwind!",
  g = { {"gerecht", "dish"}, {"ingrediënten", "ingredients (ingrediënt)"}, {"volhouden", "to last, keep going"}, {"ploeteren", "to trudge, toil"}, {"tongen", "tongues (tong)"}, {"schildpadden", "turtles (schildpad)"}, {"kust", "coast"}, {"baai", "bay"}, {"zomaar", "just any"}, {"gespleten", "forked, split (splijten)"}, {"men zegt", "they say"}, {"bijzondere", "distinct, special (bijzonder)"}, {"kooktechnieken", "cooking techniques"}, {"naar boven te halen", "to bring out (naar boven halen)"}, {"uiteindelijk", "eventually"} },
},

[1260] = { en = "Morgan Stern", tier = 3,
  t = "Morgan Stern",
  d = "Ik maak een nieuw menu voor het restaurant. Het wordt vol landelijke gerechten met een \"bayou\"-thema. Ik denk dat mijn klanten in de Blue Recluse ze heerlijk zullen vinden!$B$BIk heb mijn neef Morgan naar Theramore gestuurd, een stad aan de rand van de Dustwallow Marsh. Hij verzamelt daar recepten van de mensen die er wonen, en ik moet weten wat hij tot nu toe gevonden heeft.$B$BDe reis naar Theramore is lang. Te lang voor mij. Maar ik wed dat een jonge $c zoals jij graag de kans grijpt om te reizen, toch?",
  o = "Praat met Morgan Stern in Theramore.",
  c = "O, mijn oom heeft je gestuurd?$b$bNou, ik doe onderzoek naar recepten en ik heb een paar aanwijzingen, maar ik heb hulp nodig.$b$bHulp van iemand die natte voeten durft te krijgen.",
  g = { {"landelijke", "rural (landelijk)"}, {"gerechten", "dishes (gerecht)"}, {"bayou", "bayou (a slow, swampy river)"}, {"thema", "theme"}, {"klanten", "customers, clientele (klant)"}, {"recepten", "recipes (recept)"}, {"tot nu toe", "so far"}, {"ik wed", "I bet (wedden)"}, {"grijpt", "grabs, jumps at (grijpen)"}, {"aanwijzingen", "leads, clues (aanwijzing)"}, {"natte voeten", "wet feet"}, {"durft", "dares (durven)"} },
},

[1285] = { en = "Daelin's Men", tier = 3,
  t = "De mannen van Daelin",
  d = "Reddon... Redpath... Ah, hier is het! Lieutenant Paval Reethe.$b$bHij ging bij de wacht van Theramore, samen met de meeste rekruten die met Lady Proudmoore over de zee kwamen. Op zijn zestiende ging hij in dienst bij de mariniers van Kul Tiras. Uitstekende dienst, promoties...$b$bGeregistreerd als vermist.",
  o = "Breng de informatie over Reethe terug naar Captain Garran Vimes in Theramore.",
  c = "Vermist? Dat is Tesorans vriendelijke manier om verrader te zeggen.$B$BHij is vast een van die dwazen die zo blind trouw zijn aan Admiral Daelin dat ze verraders zijn geworden. Is dat geen heerlijke ironie? De deserteurs beschuldigen ons ervan dat wij de Alliance verraden.",
  g = { {"wacht", "guard"}, {"rekruten", "recruits (rekruut)"}, {"op zijn zestiende", "at the age of sixteen"}, {"in dienst", "into service, enlisted"}, {"mariniers", "marines (marinier)"}, {"uitstekende", "distinguished, excellent (uitstekend)"}, {"promoties", "promotions (promotie)"}, {"geregistreerd", "listed, registered (registreren)"}, {"vermist", "missing"}, {"verrader", "traitor"}, {"dwazen", "fools (dwaas)"}, {"trouw", "loyal"}, {"ironie", "irony"}, {"deserteurs", "deserters (deserteur)"}, {"beschuldigen", "accuse"}, {"verraden", "betray"} },
},

[1286] = { en = "The Deserters", tier = 3,
  t = "De deserteurs",
  d = "Het was moeilijk om in het moeras aanwezig te blijven. Maar door onze vastberadenheid hebben we in het gebied een paar verdedigende wachttorens kunnen houden.$b$bVolgens de laatste informatie en verkenningsrapporten die ik heb gekregen, heeft een groep deserteurs onze verlaten toren bij Lost Point gekraakt, ten zuidoosten van de herberg.$b$bDe leider van de deserteurs is een man die Jacken heet. Kijk of je wat informatie uit hem kunt krijgen.$b$bWees gewaarschuwd, $n. Hij is misschien een harde noot om te kraken.",
